import Foundation

/// A clip as the tutorials' clip filter sees it (spec §11 TU-2 (3)): the five
/// keys a `needs`, a `selection` wait or a `$pick` may name, answered for one
/// clip of one snapshot.
///
/// `tools/proof/tutorial_probe.swift` answers these per clip of the bundled
/// practice project, so `tutorial_check.py` can hold every tutorial's `needs`
/// to it (TU-7); TU2's runner calls `matches(_:)` for its waits and picks.
struct TutorialClipFacts: Equatable {
    /// The filter's keys, in TU-2 (3)'s order; `dictionary` answers exactly these.
    static let keys = ["has_sound", "has_pixels", "kind", "follows_clip", "has_transition"]
    /// `kind`'s values: every `ClipSource` case name.
    static let kinds = ["media", "still", "image", "text", "shape", "graphic", "nest", "adjustment"]

    /// The clip has an `audio` group.
    let hasSound: Bool
    /// The clip has a `video` group and is not an adjustment clip (which grades
    /// what is behind it and draws nothing of its own).
    let hasPixels: Bool
    /// The `ClipSource` case name (`ClipSource.kindName`).
    let kind: String
    /// The previous clip on its track (by start, then id) exists and this clip
    /// starts at or before that clip's end.
    let followsClip: Bool
    /// The clip's `transition_in` is not null.
    let hasTransition: Bool

    init(clip: ClipSnapshot, in snapshot: ProjectSnapshot) {
        hasSound = clip.audio != nil
        if case .adjustment = clip.source {
            hasPixels = false
        } else {
            hasPixels = clip.video != nil
        }
        kind = clip.source.kindName
        let earlier = snapshot.clips.filter {
            $0.track == clip.track && $0.id != clip.id
                && ($0.start < clip.start || ($0.start == clip.start && $0.id < clip.id))
        }
        let previous = earlier.max { lhs, rhs in
            lhs.start != rhs.start ? lhs.start < rhs.start : lhs.id < rhs.id
        }
        if let previous {
            followsClip = clip.start <= previous.start + previous.duration
        } else {
            followsClip = false
        }
        hasTransition = clip.transitionIn != nil
    }

    /// The five keys and their values, as the filter spells them.
    var dictionary: [String: Any] {
        [
            "has_sound": hasSound,
            "has_pixels": hasPixels,
            "kind": kind,
            "follows_clip": followsClip,
            "has_transition": hasTransition,
        ]
    }

    /// Whether every key `filter` names holds here (`{}` matches any clip). A
    /// key outside `keys`, or a value of the wrong type, matches nothing.
    func matches(_ filter: [String: Any]) -> Bool {
        let mine = dictionary
        for (key, wanted) in filter {
            guard let have = mine[key] else { return false }
            if let have = have as? String {
                guard let wanted = wanted as? String, wanted == have else { return false }
            } else if let have = have as? Bool {
                guard let wanted = wanted as? Bool, wanted == have else { return false }
            } else {
                return false
            }
        }
        return true
    }
}
import Foundation

/// Where an inspector section lives: its tab and, on the Clip tab, its
/// sub-tab (nil on every other tab).
struct TutorialSectionHome: Equatable {
    let tab: InspectorTab
    let subTab: ClipSubTab?
}

/// The names a tutorial step may point at (spec §11 TU-2 (6)): the fixed
/// controls, every inspector section with its home, and the two clip
/// references. Nothing resolves a name to a view yet (TU3 does); the table is
/// what `tools/proof/tutorial_check.py` reads, through
/// `tools/proof/tutorial_probe.swift`'s `manifest()`, to refuse a guide page
/// that names a control the app does not have. The checker also fails when
/// `sections` and the section id literals in `app/Sources` differ.
enum TutorialTargets {
    static let sectionPrefix = "section:"
    static let clipPrefix = "clip:"
    static let clipRefs: [String] = ["$selection", "$created"]

    /// Every fixed name, and the control it names, one line each.
    static let fixed: [String: String] = {
        var names: [String: String] = [
            "timeline.clips": "the timeline's clip area",
            "ruler": "the timeline's ruler, where the playhead is dragged",
            "canvas": "the preview canvas",
            "toolbar.play": "the toolbar's Play button",
            "toolbar.timecode": "the toolbar's timecode readout",
            "toolbar.export": "the toolbar's Export… button",
            "timeline.bar.split": "the timeline bar's Split (scissors) button",
            "timeline.bar.trim_start": "the timeline bar's Trim Start button",
            "timeline.bar.trim_end": "the timeline bar's Trim End button",
            "timeline.bar.ripple_delete": "the timeline bar's Ripple Delete button",
            "timeline.bar.add_marker": "the timeline bar's Add Marker button",
            "timeline.bar.duplicate": "the timeline bar's Duplicate button",
            "timeline.bar.add_text": "the timeline bar's Add Text button",
            "timeline.bar.add_shape": "the timeline bar's Add Shape button",
            "sheet.export.format": "the export sheet's Format popup",
            "sheet.export.size": "the export sheet's Size popup",
            "sheet.export.frame_rate": "the export sheet's Frame rate popup",
            "sheet.export.quality": "the export sheet's Quality popup",
            "sheet.export.loudness": "the export sheet's Loudness popup",
            "sheet.export.range": "the export sheet's Range popup",
            "sheet.export.export": "the export sheet's Export… button",
            "sheet.export.add_to_queue": "the export sheet's Add to Queue button",
            "sheet.export.cancel": "the export sheet's Cancel button",
        ]
        for tab in InspectorTab.allCases {
            names["inspector.tab.\(tab.title.lowercased())"] = "the inspector's \(tab.title) tab"
        }
        for subTab in ClipSubTab.allCases {
            names["inspector.sub_tab.\(subTab.rawValue)"] =
                "the Clip tab's \(subTab.title) sub-tab"
        }
        return names
    }()

    /// Every `InspectorSection` id in `app/Sources` and where it lives:
    /// `ClipPane.makeSections()` for the Clip tab's sub-tabs (Shadow, built
    /// by `inspectorShadowSection`, on Picture), `DocumentPane` and
    /// `MediaPane` for theirs.
    static let sections: [String: TutorialSectionHome] = {
        var table: [String: TutorialSectionHome] = [:]
        func clip(_ subTab: ClipSubTab, _ ids: [String]) {
            for id in ids { table[id] = TutorialSectionHome(tab: .clip, subTab: subTab) }
        }
        func other(_ tab: InspectorTab, _ ids: [String]) {
            for id in ids { table[id] = TutorialSectionHome(tab: tab, subTab: nil) }
        }
        clip(.text, [
            "text.content", "text.font", "text.style", "text.outline", "text.backdrop",
            "text.box", "text.animation", "text.presets",
        ])
        clip(.shape, ["shape.kind", "shape.stroke", "shape.fill", "shape.gradient", "shape.arrows"])
        clip(.graphic, ["graphic.source", "graphic.properties", "graphic.size", "graphic.timeline"])
        clip(.picture, [
            "video.transform", "video.crop", "video.corner", "video.chroma", "video.shadow",
            "video.filters", "video.reflection", "video.spotlight", "video.obscure",
        ])
        clip(.color, [
            "video.adjustment", "video.qualifier", "video.light", "video.color", "video.wheels",
            "video.curves", "video.look",
        ])
        clip(.sound, [
            "audio.volume", "audio.fades", "audio.duck", "audio.noise", "audio.compressor",
            "audio.mix",
        ])
        clip(.clip, ["clip.timing", "video.speed", "video.transition", "video.motion"])
        other(.document, ["doc.summary", "doc.canvas", "doc.rate", "doc.appearance", "doc.markers"])
        other(.media, ["media.files", "media.camera_log", "media.hdr10"])
        return table
    }()

    /// The table as JSON-ready values, for the checker:
    /// `{"fixed": [sorted names], "sections": {id: {"tab", "sub_tab" | null}},
    /// "clip_refs", "tabs", "sub_tabs"}`, a tab by its title lowercased and a
    /// sub-tab by its raw value — the spellings a step's `reveal` uses.
    static func manifest() -> [String: Any] {
        var homes: [String: Any] = [:]
        for (id, home) in sections {
            homes[id] = [
                "tab": home.tab.title.lowercased(),
                "sub_tab": home.subTab.map { $0.rawValue as Any } ?? NSNull(),
            ] as [String: Any]
        }
        return [
            "fixed": fixed.keys.sorted(),
            "sections": homes,
            "clip_refs": clipRefs,
            "tabs": InspectorTab.allCases.map { $0.title.lowercased() },
            "sub_tabs": ClipSubTab.allCases.map(\.rawValue),
        ]
    }
}
import Foundation

// MARK: - The dev-tools seam: tools compiled only under FRAMEJOB_DEV_TOOLS

/// Where the dev tools live (road map 11, spec §11 V-1 and V-2).
///
/// **The flag.** `FRAMEJOB_DEV_TOOLS` is a Swift compilation condition that
/// Debug and Release set and the Distribution configuration does not
/// (`project.yml`), so every proof and agent session, which launch Release,
/// has the dev tools and the binary `make dist` builds has none of their
/// code (V-1). A dev tool is an ORDINARY tool (V-2): a handler in
/// `devHandlers`, a row from `devTools()`, and nothing else — the parity
/// check, the argument gate and the schema checks cover it as they cover a
/// product tool, in both builds, because both tables are merged before any
/// of them reads.
///
/// **Why the check greps a marker, not tool names.** Swift string literals
/// of 15 UTF-8 bytes or fewer are stored inline in the code of an `-O`
/// binary, not as contiguous bytes, so a short tool name such as
/// `snapshot_ui` (11) can never be found in either build and an absence
/// check on it would pass for nothing. `tools/proof/dist_check.py` reads
/// `devToolsMarker` out of this file instead — at least 16 bytes — and
/// requires it present in Release's binary and absent from Distribution's.
///
/// **What keeps the marker live.** The flag-on `devTools()` logs it, so the
/// optimiser cannot drop the literal. V2 adds rows and handlers here with no
/// edit to the check.
///
/// **Where the rows go.** `catalogJSON()` splices `devTools()` in
/// immediately BEFORE the file tools, never at the end: the catalog's last
/// eleven names are the file group plus `record_screen`, which
/// `recording_probe.py` asserts. Swift takes no `#if` inside a dictionary
/// literal, so `AgentServer.swift` merges `devHandlers` through
/// `withDevHandlers` and `devOffMainTools` by a union, one line each.
extension AgentServer {
    typealias ToolHandler = (AgentServer) -> ([String: Any]) throws -> String

    /// `product` with `devHandlers` merged in. A dev tool that reuses a
    /// product tool's name keeps the PRODUCT handler and complains the way
    /// the startup parity check does.
    static func withDevHandlers(_ product: [String: ToolHandler]) -> [String: ToolHandler] {
        var merged = product
        for (name, handler) in devHandlers.sorted(by: { $0.key < $1.key }) {
            if merged[name] != nil {
                let msg = "dev tool \(name) reuses a product tool's name"
                assertionFailure(msg)
                NSLog("Frame Job: %@", msg)
                continue
            }
            merged[name] = handler
        }
        return merged
    }

    /// Every dev tool's name, in either build (empty in Distribution): the
    /// assistant withholds each one (spec §11 AI-7, `AssistantToolTable`).
    static var devToolNames: Set<String> { Set(devHandlers.keys) }

    #if FRAMEJOB_DEV_TOOLS
    // dist_check.py parses the next line (D1) and requires it bare — nothing after the
    // closing quote — at least 16 bytes, present in Release's binary, absent from Distribution's.
    static let devToolsMarker = "framejob-dev-tools-compiled-in"

    private static let devHandlers: [String: ToolHandler] = [
        // AgentServer+Snapshot.swift
        "snapshot_ui": { $0.snapshotUI },
        // AgentServer+MenuItem.swift
        "perform_menu_item": { $0.performMenuItem },
        "cancel_sheet": { $0.cancelSheet },
        // AgentServer+InspectorTab.swift
        "select_inspector_tab": { $0.selectInspectorTab },
        // AgentServer+Assistant.swift
        "assistant_send": { $0.assistantSend },
        "assistant_answer": { $0.assistantAnswer },
        // AgentServer+PlayPreview.swift
        "play_preview": { $0.playPreview },
        // AgentServer+GraphicMemory.swift
        "graphic_memory": { $0.graphicMemory },
    ]

    static let devOffMainTools: Set<String> = [
        "snapshot_ui", "perform_menu_item", "cancel_sheet", "assistant_send", "assistant_answer",
        "play_preview", "graphic_memory",
    ]

    /// The dev tools' catalog rows, in catalog order: `snapshot_ui` (V2a),
    /// `perform_menu_item` and `cancel_sheet` (V2b), `select_inspector_tab`
    /// (V3), `assistant_send` and `assistant_answer` (road map 12 A1),
    /// `play_preview` (issue #127, G-36), `graphic_memory` (issue #127,
    /// G-37). The log is what keeps `devToolsMarker` in the optimised binary;
    /// it never says `Frame Job: `, the prefix a proof reads as the parity
    /// check complaining.
    func devTools() -> [[String: Any]] {
        let rows: [[String: Any]] = [
            snapshotUITool(), performMenuItemTool(), cancelSheetTool(), selectInspectorTabTool(),
            assistantSendTool(), assistantAnswerTool(), playPreviewTool(), graphicMemoryTool(),
        ]
        NSLog("Frame Job agent server: %@, %ld dev tools", Self.devToolsMarker, rows.count)
        return rows
    }
    #else
    private static let devHandlers: [String: ToolHandler] = [:]

    static let devOffMainTools: Set<String> = []

    /// Distribution ships no dev tools.
    func devTools() -> [[String: Any]] {
        []
    }
    #endif
}

