    /// person's edit; `userInfo["refusal"]` is the `ReelRefusal`, whose
    /// sentence the inspector's foot shows (spec §11 CI-10).
    static let projectDocumentDidRefuse = Notification.Name("FrameJobProjectDocumentDidRefuse")
}

