/// (spec §5.5) and every edit and undo makes a new one, so this one keeps
/// the timeline as it was confirmed however the document changes, and
/// `Exporter` publishes it on a `RecipeSource` key of its own so even the
/// frames the compositor serves the write come from it. `mediaURLs()` is
/// the half that would otherwise leak: it resolves each bookmark and asks
/// the filesystem whether the file is there, so a job that called it at
/// RUN time would silently pick up a Relink… or a moved file from after it
/// was queued — the exact change an immutable job exists to exclude. A job
/// therefore holds the answer and no document to ask again.
///
/// Playback is NOT paused, unlike `beginExport`: a queued job runs behind
/// the editor by design, and the person who chose not to wait for it did
/// not ask for their preview to stop.
func enqueueExport(settings: ExportSettings, to url: URL, options: RecipeOptions = .none) {
    guard let document = document else {
        NSSound.beep()
        return
    }
    ExportQueueController.shared.enqueue(
        project: document.project, urls: document.mediaURLs(), settings: settings,
        to: url, options: options,
        graphics: GraphicRegistry.shared.snapshot(for: document.recipeKey))
    // Adding to a queue shows the queue: the job has no sheet of its own,
    // so this window is the only thing that says it exists.
    ExportQueueWindowController.shared.show()
}

// MARK: - Speed

/// Clip ▸ Speed…. Only `media` clips can take `set_speed` (spec §6 makes
/// it an error, not a refusal, on any other kind), so the sheet is opened
            throw Self.coreRefusal(error)
        }
        return (
            document, document.project, document.mediaURLs(), settings,
            GraphicRegistry.shared.snapshot(for: document.recipeKey)
        )
    }
    let (document, project, urls, settings, graphics) = prepared
    let url = try Self.requireFolder(
        of: Self.destinationURL(path, extension: Exporter.fileExtension(for: settings)))

    // The graphics gate, here rather than only in the writer: a module
    // that does not compile refuses the CALL, so nothing is queued that
    // could only fail (`Exporter.graphicsRefusal`, the writer's own gate).
    if let refusal = Exporter.graphicsRefusal(
        project: project, settings: settings, graphics: graphics)
    {
        throw ToolError(message: refusal.localizedDescription)
    }
    let (id, status) = onMain { () -> (UInt64, String) in
        // The editor pauses before its own export so the player is not
        // decoding the same media; the agent's does the same.
        self.editor(document)?.playback.pause()
        let id = ExportQueueController.shared.enqueue(
            project: project, urls: urls, settings: settings, to: url, options: options,
            graphics: graphics)
        AgentExports.shared.track(
            id, settings: settings, burnInTimecode: options.burnInTimecode, started: started)
        let word = ExportQueueController.shared.job(id).map {
            Self.exportStatusWord($0.state)
        }
        return (id, word ?? "queued")
    }
    return try jsonResult(["export_id": id, "path": url.path, "status": status])
}

