def check_practice(document: dict, facts: dict, practice: Path) -> list:
    """The practice project's problems (spec §11 TU-7): its read, its clips'
    keys, its media inside its package, each tutorial's `needs.clip` met by a
    clip, and its files against SHA256SUMS."""
    problems = []

    def add(message, page=PACKAGE_NAME, tid=None):
        problems.append(Problem(page, 0, tid, None, message))

    block = facts.get("practice")
    if not isinstance(block, dict) or "error" in block:
        add("the probe did not read the practice project: "
            + (str(block["error"]) if isinstance(block, dict) else "no `practice` in its facts"))
    else:
        clips = block.get("clips") or []
        want = {"id"} | set(FILTER_KEYS)
        for clip in clips:
            if not isinstance(clip, dict) or set(clip) != want:
                add(f"a practice clip's keys are not id and {', '.join(FILTER_KEYS)}: "
                    f"{sorted(clip) if isinstance(clip, dict) else clip!r}")
        inside = str(block.get("package", "")).rstrip("/") + "/media/"
        for path in block.get("media") or []:
            if not isinstance(path, str) or not path.startswith(inside):
                add(f"a practice media resolves to {path!r}, not inside {inside!r}")
        for page in document["pages"]:
            for tutorial in page["tutorials"]:
                needs = tutorial["needs"]
                wanted = needs.get("clip") if isinstance(needs, dict) else None
                if not isinstance(wanted, dict):
                    continue
                if not any(isinstance(clip, dict) and _matches(clip, wanted) for clip in clips):
                    add(f"no practice clip meets needs.clip "
                        f"{json.dumps(wanted, ensure_ascii=False)}",
                        page=page["page"], tid=tutorial["id"])
    for message in sums_problems(practice):
        add(message, page=SUMS_PAGE)
    return problems


